import{mathSheet,wordSearch,spellingSheet}from'./engine.mjs';
const $=s=>document.querySelector(s);let mode=document.body.dataset.mode||'math',sheets=[],keyVisible=false;
const titles={math:'Math practice',weekly:'A week of little wins',spelling:'Spelling practice',wordsearch:'Word explorer',handwriting:'Handwriting practice'};
function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
function settings(){return{operation:$('#operation').value,level:$('#level').value,count:Number($('#count').value)}}
function configure(){document.querySelectorAll('[data-mode]').forEach(b=>{if(b.tagName==='BUTTON'){b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',b.dataset.mode===mode)}});$('#math-fields').hidden=!['math','weekly'].includes(mode);$('#word-fields').hidden=!['spelling','wordsearch'].includes(mode);$('#hand-fields').hidden=mode!=='handwriting';$('#sheet-title').value=titles[mode];$('#mode-title').textContent=mode==='weekly'?'Build your five-day pack':'Make it your own';generate()}
function generate(){try{$('#error').textContent='';const title=$('#sheet-title').value.trim()||titles[mode];sheets=Array.from({length:mode==='weekly'?5:1},(_,i)=>{const obj={title:mode==='weekly'?`${title} · Day ${i+1}`:title,mode};if(['math','weekly'].includes(mode))obj.items=mathSheet(settings());if(mode==='spelling')obj.items=spellingSheet($('#words').value);if(mode==='wordsearch')obj.search=wordSearch($('#words').value);if(mode==='handwriting'){obj.text=$('#hand-text').value.trim().slice(0,65);if(!obj.text)throw Error('Enter a name or short sentence to practise.')}return obj});keyVisible=false;render();$('#status').textContent=`${sheets.length===5?'5 worksheets':'Worksheet'} ready · ${$('#answers').checked?'answer key included':'no answer key'}`;}catch(e){$('#error').textContent=e.message;sheets=[];$('#paper').replaceChildren(el('p',e.message));$('#status').textContent='Check your settings';}}
function paper(sheet,key=false){const p=el('section',undefined,'paper');p.append(el('small','NEPOCORE / A LITTLE PRACTICE, EVERY DAY'),el('h3',sheet.title+(key?' · Answers':'')),el('div',key?'Answer key · For parents and teachers':'Name: ____________________     Date: ______________','name'));if(sheet.search){const grid=el('div',undefined,'wordgrid'),marked=new Set(sheet.search.placements.flatMap(p=>p.cells.map(c=>c.join(','))));sheet.search.grid.forEach((row,y)=>row.forEach((letter,x)=>{const cell=el('span',letter);if(key&&marked.has(`${y},${x}`)){cell.style.background='#d7e6c8';cell.style.fontWeight='bold'}grid.append(cell)}));p.append(grid,el('div',sheet.search.words.join('   '),'words'));}else if(sheet.text){p.append(el('p','Read the model, then copy it on the lines below.'));for(let i=0;i<6;i++)p.append(el('div',i<3?sheet.text:'','copyrow'));}else{const q=el('div',undefined,'questions');if(mode==='spelling'||sheet.mode==='spelling')q.style.gridTemplateColumns='1fr';sheet.items.forEach((item,i)=>{const r=el('div',undefined,'question');r.append(el('small',String(i+1).padStart(2,'0')),el('span',item.q));r.append(key?el('strong',item.a):el('span','','line'));q.append(r)});p.append(q)}p.append(el('div','Made with Nepocore · Free to print for home and classroom use','paperfoot'));return p}
function render(){const node=paper(sheets[0],keyVisible);node.id='paper';$('#paper').replaceWith(node);$('#key-button').textContent=keyVisible?'Show worksheet':'Preview answers';$('#key-button').hidden=mode==='handwriting';}
function allPages(){return sheets.flatMap(s=>$('#answers').checked&&s.mode!=='handwriting'?[{s,key:false},{s,key:true}]:[{s,key:false}])}
function toast(text){$('#toast').textContent=text;setTimeout(()=>$('#toast').textContent='',4500)}
$('#generate').onclick=()=>{generate();if(sheets.length)toast(mode==='weekly'?'Five fresh days of practice are ready.':'Fresh worksheet ready. Make a little progress!')};document.querySelectorAll('button[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;configure()});$('#key-button').onclick=()=>{if(!sheets.length)return;keyVisible=!keyVisible;render()};$('#print').onclick=()=>{if(!sheets.length)return;$('#print-root').replaceChildren(...allPages().map(({s,key})=>paper(s,key)));let style=$('#print-size');if(!style){style=el('style');style.id='print-size';document.head.append(style)}style.textContent=`@page{size:${$('#paper-size').value==='letter'?'letter':'A4'};margin:10mm}`;window.print()};$('#answers').onchange=()=>{if(sheets.length)$('#status').textContent=`${sheets.length===5?'5 worksheets':'Worksheet'} ready · ${$('#answers').checked?'answer key included':'no answer key'}`};
$('#region').onchange=()=>{$('#paper-size').value=$('#region').value==='us'?'letter':'a4';toast('Paper size updated. You can change it below.')};
$('#download').onclick=async()=>{if(!sheets.length)return;const button=$('#download');button.disabled=true;button.textContent='Creating PDF…';try{if(!window.PDFLib)throw Error('PDF library is still loading. Try again, or use Print.');const{PDFDocument,StandardFonts,rgb}=window.PDFLib;const pdf=await PDFDocument.create(),font=await pdf.embedFont(StandardFonts.Helvetica),bold=await pdf.embedFont(StandardFonts.HelveticaBold);const unicode=s=>String(s).replace(/−/g,'-').replace(/·/g,' / ');for(const{s,key}of allPages()){const size=$('#paper-size').value==='letter'?[612,792]:[595.28,841.89],page=pdf.addPage(size);let y=size[1]-50;const text=(t,x,yy,sz=12,f=font,color=rgb(.16,.25,.19))=>{let safe=unicode(t);try{page.drawText(safe,{x,y:yy,size:sz,font:f,color})}catch{throw Error('PDF supports Latin text here. Use Print / Save as PDF for other scripts.')}};text('NEPOCORE / PRINTABLE STUDIO',45,y,9);y-=40;const title=(s.title+(key?' / Answers':'')).slice(0,70);text(title,45,y,Math.min(21,450/(title.length*.55)),bold);y-=30;text(key?'Answer key / For parents and teachers':'Name: ____________________     Date: ______________',45,y,10);y-=35;if(s.search){const cells=new Set(s.search.placements.flatMap(p=>p.cells.map(c=>c.join(','))));s.search.grid.forEach((row,r)=>row.forEach((letter,c)=>{const x=60+c*33,yy=y-r*25;if(key&&cells.has(`${r},${c}`))page.drawRectangle({x:x-4,y:yy-4,width:20,height:20,color:rgb(.85,.92,.8)});text(letter,x,yy,13,bold)}));y-=380;let line='';for(const w of s.search.words){if(line.length+w.length>58){text(line,45,y,11);y-=20;line=''}line+=w+'   '}if(line)text(line,45,y,11)}else if(s.text){for(let i=0;i<6;i++){if(i<3)text(s.text,45,y,Math.min(20,490/(s.text.length*.55)),font,rgb(.65,.7,.6));page.drawLine({start:{x:45,y:y-12},end:{x:size[0]-45,y:y-12},color:rgb(.7,.74,.67),thickness:.6});y-=65}}else{const one=s.mode==='spelling',rows=Math.ceil(s.items.length/(one?1:2));const gap=Math.min(45,(y-65)/rows);s.items.forEach((it,i)=>{const col=one?0:i%2,row=one?i:Math.floor(i/2),x=45+col*260,yy=y-row*gap;const content=`${i+1}. ${it.q} ${key?it.a:'________'}`;text(content,x,yy,one?Math.min(13,480/(content.length*.55)):13)})}text('Free for home and classroom use / nepocore.com/worksheets/',45,25,8)}pdf.setTitle(sheets[0].title);pdf.setAuthor('Nepocore');const bytes=await pdf.save();const u=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));const a=el('a');a.href=u;a.download=`nepocore-${mode}-practice.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);toast('Your PDF is ready. A little practice goes a long way!')}catch(e){$('#error').textContent=e.message;toast('Could not create PDF. Check the message under settings.')}finally{button.disabled=false;button.textContent='Download PDF ↓'}};
document.querySelectorAll('#operation,#level,#count').forEach(e=>e.addEventListener('change',generate));
let pending;document.querySelectorAll('#sheet-title,#words,#hand-text').forEach(e=>e.addEventListener('input',()=>{clearTimeout(pending);pending=setTimeout(generate,350)}));
configure();
